import sys; sys.path.insert(0,'tools/seed')
from lib import A
A("ngu-hanh-tuong-sinh-tuong-khac","Ngũ hành tương sinh tương khắc: bảng tóm tắt dễ nhớ","menh-phong-thuy","Ngũ hành Kim Mộc Thủy Hỏa Thổ, quy luật tương sinh, tương khắc và cách vận dụng trong chọn màu, vật phẩm, tuổi hợp.",
"""<h2>Ngũ hành là gì?</h2><p>Ngũ hành gồm năm yếu tố Kim, Mộc, Thủy, Hỏa, Thổ. Trong triết học phương Đông, chúng không chỉ là vật chất mà là năm trạng thái vận động, có quan hệ sinh và khắc lẫn nhau.</p>
<h2>Quy luật tương sinh</h2><ul><li>Mộc sinh Hỏa (gỗ cháy thành lửa).</li><li>Hỏa sinh Thổ (tro tàn thành đất).</li><li>Thổ sinh Kim (đất chứa kim loại).</li><li>Kim sinh Thủy (kim loại ngưng tụ nước, theo cách hiểu cổ).</li><li>Thủy sinh Mộc (nước nuôi cây).</li></ul>
<h2>Quy luật tương khắc</h2><ul><li>Mộc khắc Thổ.</li><li>Thổ khắc Thủy.</li><li>Thủy khắc Hỏa.</li><li>Hỏa khắc Kim.</li><li>Kim khắc Mộc.</li></ul>
<h2>Vận dụng thế nào?</h2><p>Người ta dùng ngũ hành để chọn màu sắc, vật phẩm, hướng nhà hợp bản mệnh; để xem tuổi nào sinh trợ hoặc khắc chế nhau; và để cân bằng bố trí không gian. Nguyên tắc thường gặp: ưu tiên hành bản mệnh và hành sinh ra bản mệnh, hạn chế hành khắc bản mệnh.</p>
<h2>Đừng hiểu quá cứng nhắc</h2><p>Khắc không đồng nghĩa với xấu tuyệt đối. Trong nhiều tài liệu, khắc vừa phải còn là sự cân bằng. Mệnh của một người cũng chỉ là một yếu tố trong bức tranh lớn.</p>
<p>Muốn biết mệnh của mình, hãy dùng <a href="/menh-ngu-hanh">Tra cứu mệnh theo năm sinh</a>.</p>
<h2>Câu hỏi thường gặp</h2><h3>Mệnh của người sinh cùng năm có giống nhau không?</h3><p>Cùng năm âm lịch thì cùng nạp âm, nhưng cá tính mỗi người vẫn khác nhau.</p>""")
A("nap-am-la-gi","Mệnh nạp âm là gì? Cách tra mệnh theo năm sinh","menh-phong-thuy","Mệnh nạp âm gắn với cặp Can Chi, gồm 30 nạp âm thuộc 5 hành. Cách hiểu và tra mệnh theo năm sinh.",
"""<h2>Nạp âm là gì?</h2><p>Mệnh trong dân gian thường là mệnh nạp âm: một hành (Kim, Mộc, Thủy, Hỏa, Thổ) kèm tên hình ảnh như Hải Trung Kim (vàng đáy biển) hay Đại Khê Thủy (nước khe lớn). Cứ hai năm liên tiếp trong chu kỳ 60 năm chung một nạp âm, nên có 30 nạp âm.</p>
<h2>Cách tra mệnh theo năm sinh</h2><ul><li>Xác định Can Chi năm sinh âm lịch (xem bài <a href="/cam-nang/can-chi-la-gi">Can Chi là gì</a>).</li><li>Tra bảng 60 hoa giáp để biết nạp âm.</li></ul><p>Cách nhanh nhất là dùng <a href="/menh-ngu-hanh">Tra cứu mệnh</a> hoặc các trang theo năm, ví dụ <a href="/1995-menh-gi">1995 mệnh gì</a>.</p>
<h2>Mệnh dùng để làm gì?</h2><ul><li>Chọn màu sắc hợp mệnh.</li><li>Xem tuổi hợp, tuổi khắc khi kết hôn, làm ăn.</li><li>Gợi ý vật phẩm, hướng bố trí.</li></ul>
<h2>Một lưu ý</h2><p>Người sinh đầu năm dương lịch nhưng trước Tết Nguyên đán thuộc năm âm lịch trước, nên mệnh cũng theo năm trước đó.</p>
<h2>Câu hỏi thường gặp</h2><h3>Mệnh nạp âm khác gì ngũ hành của Can và Chi?</h3><p>Can và Chi mỗi bên có hành riêng, còn nạp âm là hành thứ ba gắn với cặp Can Chi, thường được dùng để gọi mệnh.</p><h3>Trái mệnh có sao không?</h3><p>Theo quan niệm xưa chỉ là một yếu tố so sánh, không nên lo lắng quá mức.</p>""")
A("mau-sac-hop-menh","Màu sắc hợp mệnh: chọn màu theo ngũ hành","menh-phong-thuy","Gợi ý màu hợp và màu nên hạn chế cho 5 mệnh Kim Mộc Thủy Hỏa Thổ, dựa trên quy luật tương sinh tương khắc.",
"""<h2>Nguyên tắc chọn màu</h2><p>Mỗi hành gắn với một nhóm màu. Màu bản mệnh và màu của hành sinh ra bản mệnh thường được xem là hợp; màu của hành khắc bản mệnh nên hạn chế.</p>
<h2>Bảng gợi ý</h2><ul><li><strong>Mệnh Kim:</strong> hợp trắng, xám, ánh kim; màu hành Thổ (vàng, nâu) sinh trợ; hạn chế đỏ, cam, hồng (Hỏa).</li><li><strong>Mệnh Mộc:</strong> hợp xanh lá; màu hành Thủy (xanh dương, đen) sinh trợ; hạn chế trắng, xám (Kim).</li><li><strong>Mệnh Thủy:</strong> hợp xanh dương, đen; màu hành Kim (trắng, xám) sinh trợ; hạn chế vàng, nâu (Thổ).</li><li><strong>Mệnh Hỏa:</strong> hợp đỏ, hồng, cam, tím; màu hành Mộc (xanh lá) sinh trợ; hạn chế xanh dương, đen (Thủy).</li><li><strong>Mệnh Thổ:</strong> hợp vàng, nâu; màu hành Hỏa (đỏ, hồng) sinh trợ; hạn chế xanh lá (Mộc).</li></ul>
<h2>Áp dụng thực tế</h2><p>Bạn có thể dùng màu hợp mệnh cho quần áo, ví, xe, phòng làm việc. Không cần thay đổi toàn bộ; một vài điểm nhấn là đủ. Màu bạn thích và thoải mái cũng quan trọng không kém.</p>
<p>Tra màu cụ thể theo năm sinh tại <a href="/mau-sac-hop-menh">trang Màu sắc hợp mệnh</a> hoặc các trang như <a href="/1990-hop-mau-gi">1990 hợp màu gì</a>.</p>
<h2>Câu hỏi thường gặp</h2><h3>Có cần tránh hoàn toàn màu khắc mệnh không?</h3><p>Không. Chỉ nên hạn chế ở những vật dụng chính, dùng lượng nhỏ vẫn ổn.</p>""")
A("huong-nha-hop-tuoi","Hướng nhà hợp tuổi: cách hiểu cơ bản","menh-phong-thuy","Tìm hiểu cách người xưa chọn hướng nhà, cung phi và nguyên tắc cơ bản; nên tham khảo thế nào cho hợp lý.",
"""<h2>Vì sao có chuyện chọn hướng nhà?</h2><p>Trong phong thủy, hướng nhà được cho là ảnh hưởng đến ánh sáng, thông gió và vận khí của gia chủ. Về thực tế, hướng nhà còn tác động trực tiếp tới nắng gió và nhiệt độ trong nhà.</p>
<h2>Cung phi và Bát trạch</h2><p>Trường phái Bát trạch phân người thành hai nhóm Đông tứ mệnh và Tây tứ mệnh dựa theo năm sinh, rồi gợi ý hướng tốt xấu cho từng người. Công thức khác nhau theo giới tính nên cần tra bảng chính xác.</p>
<h2>Cách tham khảo hợp lý</h2><ul><li>Xác định cung phi của gia chủ (thường là chủ hộ).</li><li>Ưu tiên các hướng tốt cho cửa chính, bếp, phòng ngủ chính.</li><li>Đối chiếu với điều kiện lô đất, đường đi, ánh sáng.</li></ul><p>Bạn có thể dùng công cụ <a href="/huong-nha-hop-tuoi">Hướng nhà hợp tuổi</a> để tra nhanh.</p>
<h2>Cân bằng với thực tế</h2><p>Nhiều thửa đất không thể chọn hướng. Khi đó, có thể điều chỉnh vị trí bếp, giường, bàn làm việc trong nhà. Điều kiện thông thoáng, đủ sáng, an toàn nên đặt lên đầu.</p>
<h2>Câu hỏi thường gặp</h2><h3>Gia đình nhiều tuổi khác nhau xem theo ai?</h3><p>Thường ưu tiên người chủ hộ hoặc người có vai trò chính trong nhà.</p>""")
A("tam-hop-luc-hop-tuong-xung","Tam hợp, lục hợp, tương xung của 12 con giáp","tuoi-tuong-hop","Bảng tam hợp, lục hợp và lục xung của 12 con giáp, cách hiểu khi xem tuổi hợp tuổi khắc.",
"""<h2>Quan hệ giữa các con giáp</h2><p>Trong xem tuổi, người ta xét quan hệ giữa các Địa chi: hợp, xung, hại, hình, phá. Phổ biến nhất là tam hợp, lục hợp và tương xung.</p>
<h2>Tam hợp</h2><ul><li>Thân – Tý – Thìn</li><li>Dần – Ngọ – Tuất</li><li>Tỵ – Dậu – Sửu</li><li>Hợi – Mão – Mùi</li></ul>
<h2>Lục hợp</h2><ul><li>Tý – Sửu</li><li>Dần – Hợi</li><li>Mão – Tuất</li><li>Thìn – Dậu</li><li>Tỵ – Thân</li><li>Ngọ – Mùi</li></ul>
<h2>Lục xung (tương xung)</h2><ul><li>Tý – Ngọ</li><li>Sửu – Mùi</li><li>Dần – Thân</li><li>Mão – Dậu</li><li>Thìn – Tuất</li><li>Tỵ – Hợi</li></ul>
<h2>Cách hiểu</h2><p>Hợp là thuận hòa, dễ hỗ trợ. Xung là đối lập tính chất, dễ bất đồng. Tuy nhiên, quan hệ thực tế giữa hai người phụ thuộc vào cách ứng xử hơn là con giáp. Nên dùng thông tin này như gợi ý khi chọn bạn đồng hành, đối tác, ngày giờ.</p>
x
<h2>Câu hỏi thường gặp</h2><h3>Hai tuổi xung có cưới được không?</h3><p>Không có quy định cấm; nhiều gia đình chỉ cân nhắc thêm ngày giờ hoặc yếu tố khác.</p>""")
A("xem-tuoi-ket-hon","Xem tuổi kết hôn: các yếu tố người Việt thường cân nhắc","tuoi-tuong-hop","Các tiêu chí xem tuổi vợ chồng: Can Chi, Ngũ hành, cung phi, kim lâu và nên nhìn nhận ra sao.",
"""<h2>Vì sao xem tuổi kết hôn?</h2><p>Theo truyền thống, xem tuổi là cách tham khảo sự tương hợp trước khi tiến tới hôn nhân, đồng thời là dịp để hai gia đình trò chuyện, hiểu nhau hơn.</p>
<h2>Các yếu tố thường xem</h2><ul><li><strong>Thiên can và Địa chi:</strong> can hợp, chi hợp được cho là tốt.</li><li><strong>Ngũ hành bản mệnh:</strong> tương sinh được ưu tiên, tương khắc cần cân nhắc.</li><li><strong>Cung phi:</strong> theo Bát trạch, xem hai người cùng nhóm Đông hay Tây tứ mệnh.</li><li><strong>Tuổi kim lâu, hoang ốc, tam tai:</strong> một số gia đình tránh kết hôn vào năm phạm.</li></ul>
<h2>Cách tham khảo hợp lý</h2><p>Hãy xem đây là khung tham khảo. Hôn nhân bền vững dựa nhiều vào sự thấu hiểu, chia sẻ và trách nhiệm. Khi có điểm chưa hợp, các cặp đôi thường chọn ngày cưới đẹp, hoặc tin vào sự nỗ lực của chính mình.</p>
<p>Dùng công cụ <a href="/xem-tuoi-ket-hon">Xem tuổi kết hôn</a> và <a href="/xem-ngay/cuoi-hoi">ngày cưới hỏi</a> trên TriMenh để tham khảo nhanh.</p>
<h2>Câu hỏi thường gặp</h2><h3>Kết quả không hợp có phải bỏ cưới không?</h3><p>Không. Đây chỉ là thông tin tham khảo; quyết định là của hai bạn.</p>""")
A("than-so-hoc-la-gi","Thần số học là gì? Những điều cần biết cho người mới","than-so-hoc","Thần số học diễn giải ý nghĩa các con số từ ngày sinh và tên. Các chỉ số chính và cách dùng tham khảo.",
"""<h2>Thần số học là gì?</h2><p>Thần số học (Numerology) là hệ thống gán ý nghĩa cho các con số, thường được tính từ ngày sinh và họ tên, để mô tả tính cách và xu hướng. Phương pháp phổ biến hiện nay thường gắn với Pythagoras, dù mối liên hệ lịch sử này chủ yếu mang tính truyền thuyết.</p>
<h2>Các chỉ số thường gặp</h2><ul><li><strong>Số chủ đạo:</strong> tính từ ngày, tháng, năm sinh; được xem là chỉ số quan trọng nhất.</li><li><strong>Số linh hồn:</strong> tính từ các nguyên âm trong tên.</li><li><strong>Số biểu đạt:</strong> tính từ toàn bộ chữ cái trong tên.</li><li><strong>Năm cá nhân:</strong> chu kỳ năng lượng từng năm.</li></ul>
<h2>Ứng dụng</h2><p>Nhiều người dùng thần số học để hiểu điểm mạnh, điểm cần cải thiện, hoặc suy nghĩ về hướng nghề nghiệp. Đây là công cụ tự khám phá, không phải khoa học đã được kiểm chứng.</p>
<h2>Bắt đầu từ đâu?</h2><p>Hãy thử tính <a href="/than-so-hoc">số chủ đạo</a> của mình, sau đó đọc phần giải thích từng số tại <a href="/than-so-hoc/so-chu-dao-1">trang số chủ đạo</a>.</p>
<h2>Câu hỏi thường gặp</h2><h3>Dùng tên khai sinh hay tên đang dùng?</h3><p>Phần lớn tài liệu dùng tên khai sinh cho các chỉ số tên.</p>""")
A("cach-tinh-so-chu-dao","Cách tính số chủ đạo trong thần số học (có ví dụ)","than-so-hoc","Từng bước cộng các chữ số ngày sinh để ra số chủ đạo, cách xử lý số 11, 22, 33 và ví dụ cụ thể.",
"""<h2>Số chủ đạo là gì?</h2><p>Số chủ đạo (Life Path Number) là một con số từ 1 đến 9, hoặc số đặc biệt 11, 22, 33, được tính từ toàn bộ ngày tháng năm sinh.</p>
<h2>Cách tính</h2><ul><li>Cộng tất cả chữ số của ngày, tháng, năm sinh.</li><li>Nếu tổng có hai chữ số, tiếp tục cộng cho đến khi còn một chữ số.</li><li>Nếu tổng ra 11, 22 hoặc 33 thì thường giữ nguyên.</li></ul>
<h2>Ví dụ 1</h2><p>Sinh 15/08/1990: 1+5+0+8+1+9+9+0 = 33. Nhiều người giữ là số đặc biệt 33; nếu rút gọn tiếp là 3+3 = 6.</p>
<h2>Ví dụ 2</h2><p>Sinh 29/11/1992: 2+9+1+1+1+9+9+2 = 34, rút gọn 3+4 = 7. Số chủ đạo là 7.</p>
<h2>Số chủ đạo cho biết gì?</h2><p>Mỗi số gắn với một nhóm đặc điểm, ví dụ số 1 là độc lập, số 2 hợp tác, số 6 trách nhiệm. Đây là mô tả chung, không áp dụng cứng cho từng người.</p>
<p>Bạn không cần cộng tay: dùng <a href="/than-so-hoc">công cụ thần số học</a> trên TriMenh để tính nhanh.</p>
<h2>Câu hỏi thường gặp</h2><h3>Có cách tính khác nhau không?</h3><p>Có. Một số tài liệu cộng riêng ngày, tháng, năm rồi mới rút gọn, và có thể cho kết quả khác ở các số đặc biệt.</p>""")
A("so-chu-dao-11-22-33","Số chủ đạo 11, 22, 33 là gì? Ý nghĩa các số đặc biệt","than-so-hoc","Giải thích số đặc biệt 11, 22, 33 trong thần số học: nguồn gốc, đặc điểm thường được mô tả và cách hiểu cân bằng.",
"""<h2>Vì sao 11, 22, 33 được giữ nguyên?</h2><p>Trong thần số học, ba số này gọi là Master Number (số bậc thầy). Khi tính số chủ đạo, nếu tổng ra 11, 22 hoặc 33 người ta thường không rút gọn mà xem đó là một dạng năng lượng đặc biệt.</p>
<h2>Số 11</h2><p>Thường được mô tả là nhạy cảm, giàu trực giác và cảm hứng. Số 11 rút gọn là 2, nên cũng mang tính hợp tác.</p>
<h2>Số 22</h2><p>Thường gắn với khả năng biến ý tưởng lớn thành hiện thực, tư duy hệ thống. Rút gọn là 4, mang tính ổn định, thực tế.</p>
<h2>Số 33</h2><p>Thường được mô tả là tinh thần chăm sóc, cống hiến, thầy giáo. Số này ít gặp và không phải trường phái nào cũng công nhận.</p>
<h2>Đọc cho cân bằng</h2><p>Các mô tả mang tính biểu tượng. Nhiều tài liệu nhấn mạnh người mang số đặc biệt dễ chịu áp lực cao. Điều đó không phải kết luận khoa học, chỉ là gợi ý để tự nhìn lại bản thân.</p>
<p>Xem phần giải thích riêng: <a href="/than-so-hoc/so-chu-dao-11">số 11</a>, <a href="/than-so-hoc/so-chu-dao-22">số 22</a>, <a href="/than-so-hoc/so-chu-dao-33">số 33</a>.</p>
<h2>Câu hỏi thường gặp</h2><h3>Có nên đọc cả số rút gọn?</h3><p>Nhiều người đọc cả hai: số đặc biệt và số rút gọn (11→2, 22→4, 33→6).</p>""")
